import{_ as a,o as r,c as t,a5 as o}from"./chunks/framework.BwlBv862.js";const b=JSON.parse('{"title":"TikTools 4.2.1-rc.2 候选版记录","description":"","frontmatter":{"title":"TikTools 4.2.1-rc.2 候选版记录","docId":"releases.4.2.1-rc.2","translationKey":"releases.4.2.1-rc.2","locale":"zh","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"af1ea83a9bb29fd23f3e4c086d976fb5abecaff8e20965cc6db9b5c64d5b191e","translationRevision":"78301bdc4b9fd066daeb8a04e83bcea430a03478a723327d8ecdd27b20be5685","order":20},"headers":[],"relativePath":"zh/releases/4.2.1-rc.2.md","filePath":"zh/releases/4.2.1-rc.2.md","lastUpdated":1794611623000}'),c={name:"zh/releases/4.2.1-rc.2.md"};function i(d,e,l,s,n,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="tiktools-421-rc2" tabindex="-1">TikTools 4.2.1-rc.2 候选版记录 <a class="header-anchor" href="#tiktools-421-rc2" aria-label="Permalink to &quot;TikTools 4.2.1-rc.2 候选版记录 {#tiktools-421-rc2}&quot;">​</a></h1><h2 id="goal-status-and-prerequisites" tabindex="-1">目标、状态与前置条件 <a class="header-anchor" href="#goal-status-and-prerequisites" aria-label="Permalink to &quot;目标、状态与前置条件 {#goal-status-and-prerequisites}&quot;">​</a></h2><p>使用 RC2 历史说明了解针对 RC1 中复现的并发更改读取问题所做的修正。候选版记录涵盖 Actions 禁用期间本地构建的 Linux AppImage、DEB 和便携包，不能证明目前可下载，也不代表新构建了 Windows 包。请从<a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">发布列表</a>选择资源，保留校验和文件，并使用隔离配置测试。</p><p>Cloud 恢复及协作仍属实验性。昵称搜索仍依赖后端 <code>6a69c99</code> 及迁移 <code>20261113000001_remote_invitation_recipients.sql</code>；应用包不会部署这些变更。</p><h2 id="correction-and-expected-behavior" tabindex="-1">修正与预期行为 <a class="header-anchor" href="#correction-and-expected-behavior" aria-label="Permalink to &quot;修正与预期行为 {#correction-and-expected-behavior}&quot;">​</a></h2><p>更改/冲突列表及协议选择共享协议观察，不再占用产品修改槽位。无关包日志操作占用该槽位时，工具栏和面板读取仍可完成。写入屏障、账户隔离和明确的迁移决定保持不变。</p><p>账户检查拒绝退出登录、待处理转换和替换会话。读取本地比较不会恢复凭据或启动 Cloud 请求。失败时，UI 显示原生原因及本地重新加载操作；该重试不会发送、下载或解决记录。</p><h2 id="check-the-candidate" tabindex="-1">检查候选版 <a class="header-anchor" href="#check-the-candidate" aria-label="Permalink to &quot;检查候选版 {#check-the-candidate}&quot;">​</a></h2><ol><li>记录显示的 <code>4.2.1-rc.2</code> 版本，在隔离配置中打开插件 → 更改。</li><li>从工具栏和面板打开或重新加载比较。加载失败应保留原因，而非报告所有内容已同步。</li><li>使用本地重试，确认它重新加载比较，而不改变待处理队列或应用远程记录。</li><li>单独记录账户/会话转换。复现受影响配置时，对照 <a href="./4.2.1-rc.1.html">RC1 迁移流程</a>。</li></ol><h2 id="recorded-validation-and-recovery" tabindex="-1">已记录的验证与恢复 <a class="header-anchor" href="#recorded-validation-and-recovery" aria-label="Permalink to &quot;已记录的验证与恢复 {#recorded-validation-and-recovery}&quot;">​</a></h2><p>原始记录描述了确定性的 32 读取者回归、CloudAuth/同步/原生/前端检查，以及优化后的 AppImage 在空隔离配置下启动。记录了安装器内容及便携归档检查。该启动没有测试已登录的生产同步或媒体播放。</p><p>历史 AppImage SHA-256 为 <code>35fc26e7bc5875c5a3fe99bf6a84baf77af8ca63d1c8b8e61825881187d6091f</code>。它只标识记录中的文件；请使用实际下载资源附带的校验和。</p><p>加载仍失败时，保留版本、原生错误和请求 ID，再使用<a href="./../user/preferences/troubleshooting.html">诊断</a>。保留待处理编辑和冲突。RC2 时，自动化仍使用本地参考，变量和叠加层分区尚未完成，历史 SQLite 锁持有者仍未识别。这些说明不声称旧后端缺失的人员搜索路由后来已经部署。</p><p><a href="https://github.com/nglmercer/TikTools-app/blob/80c5cb1fbfa45eaeb1c086c71320a15e565d8541/docs/RELEASE-4.2.1-rc.2.md" target="_blank" rel="noreferrer">原始发布记录</a>作为带日期证据保留。返回<a href="./">发行说明索引</a>。</p>',14)])])}const f=a(c,[["render",i]]);export{b as __pageData,f as default};
